    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    int[,] visited = new int[n, n];
    visited[start[0]][start[1]] = 1;

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        int row = current[0];
        int col = current[1];

        if (row - 1 >= 0 && visited[row - 1][col] == 0) {
            queue.offer(new int[]{row - 1, col});
            visited[row - 1][col] = 1;
        }
        if (row + 1 < n && visited[row + 1][col] == 0) {
            queue.offer(new int[]{row + 1, col});
            visited[row + 1][col] = 1;
        }
        if (col - 1 >= 0 && visited[row][col - 1] == 0) {
            queue.offer(new int[]{row, col - 1});
            visited[row][col - 1] = 1;
        }
        if (col + 1 < n && visited[row][col + 1] == 0) {
            queue.offer(new int[]{row, col + 1});
            visited[row][col + 1] = 1;
        }
    }

    return "cannot be travelled";
