        List<int[]> visited = new ArrayList<>();
        Queue<int[]> queue = new LinkedList<>();
        visited.add(start);

        for (int[] path : paths) {
            if (path[0] == start[0] && path[1] == start[1]) {
                visited.add(path);
                queue.offer(path);
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();

            if (current[0] == end[0] && current[1] == end[1]) {
