public static String appx(String word1, String word2) {
    int commonChars = 0;
    int totalChars = word1.length() + word2.length();

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonChars++;
            }
        }
    }

    int numerator = commonChars;
    int denominator = totalChars;

    if (denominator == 0) {
        throw new IllegalArgumentException("One of the words contains no characters");
    }

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = calculateGCD(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    String result = "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    return result;
}

