public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    // Sort the array in ascending order
    Arrays.sort(arr);
    // Calculate the index of elements to remove (5% from both ends)
    int startToSkip = n / 20;
    int endToSkip = n - startToSkip;
    // Calculate the sum of the elements to exclude
    int sum = 0;
    for (int i = startToSkip; i <= endToSkip; i++) {
        sum += arr[i];
    }
    // Calculate the mean of the remaining elements
    return (double) sum / (n - startToSkip - endToSkip);
}

