public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize adjacency list and parent map
    Map<Integer, List<Integer>> adj = new HashMap<>();
    Map<Integer, Integer> parent = new HashMap<>();

    // Build the adjacency list and parent map
    for (int[] edge : edges) {
        adj.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        adj.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        parent.put(edge[1], edge[0]);
    }

    // Helper function to calculate time to collect all apples
    public int dfs(int node, int parent) {
        int time = 0;
        for (int neighbor : adj.get(node)) {
            if (neighbor == parent) continue; // Skip the parent
            time += dfs(neighbor, node);
        }
        time += hasApple[node] ? 2 : 0; // Add time for collecting the current node if it has an apple
        return time;
    }

    // Start DFS from node 0
    return dfs(0, -1);
}

