public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the adjacency list
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
    }

    // Initialize a stack for depth-first search traversal
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    // Initialize a hash set to keep track of visited nodes
    Set<Integer> visited = new HashSet<>();
    int time = 0;

    // Main depth-first search traversal loop
    while (!stack.isEmpty()) {
        int current = stack.pop();
        visited.add(current);
        for (int neighbor : adj.get(current)) {
            if (!visited.contains(neighbor)) {
                stack.push(neighbor);
            }
        }

        // Calculate the time to visit the current node
        int appleTime = hasApple[current] ? 2 : 0;
        for (int ancestor = 0; ancestor < current; ancestor++) {
            appleTime += hasApple[ancestor] && visited.contains(current) ? 2 : 0;
        }
        if (ancestor > 0) {
            appleTime += hasApple[ancestor] && visited.contains(current) ? 2 : 0;
        }
        time += appleTime;
    }

    return time;
}

