    ArrayList<Integer>[] adj = new ArrayList[n]; // Adjacency list representation of the tree
    boolean[] visited = new boolean[n]; // Visited array to keep track of nodes that have been visited

    // Initialize adjacency list
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }

    // Build the adjacency list from the edges
    for (int[] edge : edges) {
        adj[edge[0]].add(edge[1]);
        adj[edge[1]].add(edge[0]);
    }

    // DFS to calculate the minimum time to collect apples
    int time = dfs(adj, visited, 0, hasApple);

    // Return the minimum time + 2 (for the return path to 0)
    return time + 2;
}

public String sortString(String s) {
    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    StringBuilder result = new StringBuilder();

    while (!minHeap.isEmpty()) {
        if (minHeap.peek() == result.charAt(result.length() - 1)) {
            while (!minHeap.isEmpty() && minHeap.peek() == result.charAt(result.length() - 1)) {
                minHeap.poll();
            }
        }
        if (maxHeap.peek() == result.charAt(result.length() - 1)) {
            while (!maxHeap.isEmpty() && maxHeap.peek() == result.charAt(result.length() - 1)) {
                maxHeap.poll();
            }
        }
        if (!minHeap.isEmpty() && !maxHeap.isEmpty()) {
            char minChar = minHeap.poll();
            char maxChar = maxHeap.poll();

            result.append(minChar);
            result.append(maxChar);
        }
    }

    return result.toString();
}

public String sortString(String s) {
        StringBuilder result = new StringBuilder();
        List<Character> characters = new ArrayList<>();
        for (char c : s.toCharArray()) {
            characters.add(c);
        }
        Arrays.sort(characters);
        while (!characters.isEmpty()) {
            char first = characters.get(0);
            result.append(first);
            characters.remove(0);
            List<Character> filtered = new ArrayList<>();
            for (char c : characters) {
                if (c > first) {
                    filtered.add(c);
                }
            }
            characters = filtered;
            if (characters.isEmpty()) {
                break;
            }
            char last = characters.get(characters.size() - 1);
            result.append(last);
            characters.remove(characters.size() - 1);
            filtered = new ArrayList<>();
            for (char c : characters) {
                if (c < last) {
                    filtered.add(c);
                }
            }
            characters = filtered;
        }
        return result.toString();
    }

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();

    Queue<Character> minQueue = new PriorityQueue<>();
    Queue<Character> maxQueue = new PriorityQueue<>((o1, o2) -> o2 - o1);
    while (chars.length > 0 || !minQueue.isEmpty() || !maxQueue.isEmpty()) {
        // Collect characters from both queues
        char minChar = minQueue.isEmpty() ? '\0' : minQueue.poll();
        char maxChar = maxQueue.isEmpty() ? '\0' : maxQueue.poll();

        // Append the smallest character if it's available and not the same as the last character added to the result
        if (minChar != '\0' && result.charAt(result.length() - 1) != minChar) {
            result.append(minChar);
        }
        minQueue.offer(minChar);

        // Append the largest character if it's available and not the same as the last character added to the result
        if (maxChar != '\0' && result.charAt(result.length() - 1) != maxChar) {
            result.append(maxChar);
        }
        maxQueue.offer(maxChar);
    }

    return result.toString();
}

public String sortString(String s) {
    int[] frequency = new int[26]; // Array to store the frequency of each character
    StringBuilder result = new StringBuilder();

    // Count the frequency of each character in s
    for (char c : s.toCharArray()) {
        frequency[c - 'a']++;
    }

    // Append characters in ascending order
    for (int i = 0; i < 26; i++) {
        while (frequency[i]-- > 0) {
            result.append((char) ('a' + i));
        }
    }

    // Append characters in descending order
    for (int i = 25; i >= 0; i--) {
        while (frequency[i]-- > 0) {
            result.append((char) ('a' + i));
        }
    }

    return result.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    char[] charsToSort = new char[s.length()];
    char[] sortedChs = new char[s.length()];

    // Count occurrences of each character in the string
    for (int i = 0; i < s.length(); i++) {
        int index = s.charAt(i) - 'a';
        count[index]++;
        charsToSort[i] = s.charAt(i);
    }

    // Sort characters based on their position in the alphabet
    Arrays.sort(charsToSort, (a, b) -> a - b);

    int i = 0, j = charsToSort.length - 1;
    int sortedIndex = 0;

    // Construct the sorted string
    while (i <= j) {
        if (count[i] > 0) {
            sortedChs[sortedIndex++] = charsToSort[i];
            count[i]--;
        }
        if (count[j] > 0) {
            sortedChs[sortedIndex++] = charsToSort[j];
            count[j]--;
        }
    }

    return new String(sortedChs);
}

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        if ((totalSum & 1) != 0) {
            return false; // If the total sum is odd, it's impossible to split into two equal averages
        }
        int targetSum = totalSum / 2;

        Map<Integer, Integer> cumulativeSums = new HashMap<>();
        cumulativeSums.put(0, 1); // Ensure the base case for empty sum

        int cumulativeSum = 0;
        for (int num : nums) {
            cumulativeSum += num;
            int complement = targetSum - cumulativeSum;
            if (cumulativeSums.containsKey(complement)) {
                return true;
            }
            cumulativeSums.put(cumulativeSum, cumulativeSums.getOrDefault(cumulativeSum, 0) + 1);
        }
        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
    // If the length of the array is less than 2, it cannot be split into two non-empty arrays of different lengths with the same average
    if (nums.length < 2) {
        return false;
    }

    // Calculate the total sum of the array
    int totalSum = Arrays.stream(nums).sum();

    // Calculate the target average for each subset
    double targetAverage = totalSum / ((double) nums.length);

    double currentSum = 0.0;

    // Iterate through the array to find valid splits
    for (int num : nums) {
        currentSum += num;
        // Check if the current sum plus the running total divided by the remaining count of elements in the array is equal to the target average
        if (currentSum + targetAverage * (nums.length - 1) == totalSum) {
            return true;
        }
    }

    // If no valid splits are found, return false
    return false;
}

