    int maxLength = (int) Math.pow(2, k);
    boolean[] seen = new boolean[maxLength];

    for (int i = 0; i < s.length() - k + 1; i++) {
        int substringValue = Integer.parseInt(s.substring(i, i + k), 2);
        if (seen[substringValue]) {
            return false;
        }
        seen[substringValue] = true;
    }

    return true;
