public int minInsertions(String s) {
    int balance = 0; // Tracks the balance between '(' and ')'
    int insertions = 0; // Counts the minimum number of insertions

    for (char c : s.toCharArray()) {
        if (c == '(') {
            ++balance;
        } else {
            --balance;
            if (balance < 0) {
                // If balance goes negative, it means a closing parenthesis was encountered before a matching opening one
                ++insertions;
                balance = 1; // Reset balance to 1 for the current closing parenthesis
            }
        }
    }

    // Add the remaining left parentheses to the insertions count. After iterating through the string, balance should be non-negative
    insertions += balance;

    return insertions;
}

public int minOperations(int n) {
        // Calculate the sum of all elements in arr
        int total = n * (2 * n + 1) / 2;

        // The goal is to make all elements equal, so the target sum is 0
        // The minimum number of operations required is half of the difference between the current sum and the target sum
        return (total < 0) ? 0 : total >>> 1;
    }

public int minOperations(int n) {
    int validOperations = 0, targetValue = ((n * 3) + 1) / 4;
    for (int start = 1; start <= n / 2; start++) {
        if (start - targetValue < 0) {
            throw new IllegalArgumentException("Cannot perfrom any more operations");
        }
        validOperations += 2 * (start - targetValue);
        start++;
    }
    return validOperations;
}

public int minOperations(int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += (i * 2) + 1;
    }
    int target = sum / n;
    int totalOperations = n * target;
    return totalOperations - sum;
}

