public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int n = 0;
    while (n * n <= k) {
        fibs.add(n * n);
        n++;
    }
    Collections.reverse(fibs);
    int count = 0;
    for (int fib : fibs) {
        while (k >= fib) {
            k -= fib;
            count++;
        }
        if (k == 0) {
            return count;
        }
    }
    return -1;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = {0, 1};
    int i = 2;
    // Generate Fibonacci numbers up to k
    while (fib[i] <= k) {
        fib[i++] = fib[i - 1] + fib[i - 2];
    }
    Arrays.sort(fib);
    int count = 0;
    // Use dynamic programming to find the minimum number of Fibonacci numbers
    for (int i = fib.length - 1; i >= 0 && k > 0; i--) {
        while (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }
    return count;
}

