public String makeGood(String s) {
    // Check for adjacent characters where one is lowercase and the other is the corresponding uppercase
    for (int i = 0; i < s.length() - 1; i++) {
        if (Math.abs(s.charAt(i) - s.charAt(i + 1)) == 32) {
            // Remove one of the adjacent characters
            s = s.substring(0, i) + s.substring(i + 2);
            // Check the string again from the beginning
            return makeGood(s);
        }
    }
    // If no more adjacent characters are found to be the same, the string is good
    return s;
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder(s);
    int len = sb.length();
    int j = 1;
    while (j < len) {
        if ((sb.charAt(j - 1) > 'Z' && sb.charAt(j) < 'A') ||
            (sb.charAt(j - 1) < 'Z' && sb.charAt(j) > 'A')) {
            sb.delete(j - 1, j + 1);
            len = sb.length();
            if (len == 1) break;
            j = 1;
        } else {
            j++;
        }
    }
    return sb.toString();
}

public static String makeGood(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    StringBuilder sb = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (sb.length() > 0 && Math.abs(c - sb.charAt(sb.length() - 1)) == 32) {
            sb.deleteCharAt(sb.length() - 1);
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

