        if (i > 0 && s.charAt(i - 1) == Character.toLowerCase(s.charAt(i)) && s.charAt(i) == Character.toUpperCase(s.charAt(i + 1))) {
            s = s.substring(0, i - 1) + s.substring(i + 2);
            i = i - 2; // Adjust the index after modification
        } else {
            i++;
        }
    }
    return s;
}

public String makeGood(String s) {
    int left = 0;
