    while (right < s.length()) {
        if (left >= 0 && isGood(s.charAt(left), s.charAt(right))) {
            left--;
        }
        Character c = s.charAt(right);
        if (left < 0 || !c.equals(s.charAt(left))) {
            s = s.substring(0, left + 1) + Character.toString(c) + s.substring(right + 1);
            left = -1;
        }
        left++;
        right++;
    }
    return s;
}

