public int maxUniqueSplit(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }

        int maxUnique = 0;
        int windowStart = 0;
        Map<Character, Integer> charIndexMap = new HashMap<>();

        for (int windowEnd = 0; windowEnd < s.length(); windowEnd++) {
            char currentChar = s.charAt(windowEnd);
            charIndexMap.put(currentChar, windowEnd);

            // If the character is already in the map, it means we have found a repeating character
            while (charIndexMap.containsKey(currentChar) && charIndexMap.get(currentChar) >= windowStart) {
                // Shrink the window from the left
                windowStart = charIndexMap.get(currentChar) + 1;
            }

            //.Update the maximum unique split count
            maxUnique = Math.max(maxUnique, windowEnd - windowStart + 1);
        }

        return maxUnique;
    }

public int maxUniqueSplit(String s) {
