            while (substrings.containsKey(currentChar) && left <= right) {
                substrings.remove(s.charAt(left));
                left++;
            }
            substrings.put(currentChar, right);
            maxCount = Math.max(maxCount, right - left + 1);
        }

        return maxCount;
    }

