public static int singleNumber(int[] nums) {
    int[] counter = new int[32]; // Assuming 32-bit integers
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            counter[i] += num & 1;
            num >>= 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        result = (result << 1) + (counter[i] % 3);
    }
    return result;
}

