public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    StringBuilder result = new StringBuilder();
    while (n > 0) {
        int remainder = n % 1000;
        if (remainder > 0) {
            result.insert(0, ".");
            result.insert(0, remainder);
        } else {
            result.insert(0, remainder);
        }
        n /= 1000;
    }
    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder("");
    int length = String.valueOf(n).length();
    int groups = length / 3;

    if (length % 3 != 0) {
        groups++;
    }

    for (int i = groups - 1; i >= 0; i--) {
        if (i > 0) {
            result.insert(length - (i * 3), ".");
        }
        result.insert(0, String.valueOf(n - (n / (int) Math.pow(10, (i * 3)))) + "");
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
