public static String addThousandSeparator(int n) {
    // Ensure n is non-negative
    if (n < 0) {
        return addThousandSeparator(-n) + "-";
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (n > 0) {
        if (i != 0 && i % 3 == 0) {
            sb.append('.');
        }
        sb.append(n % 10); // Append the current digit
        n /= 10; // Remove the last digit
        i++;
    }

    // Reverse and return the result
    return new StringBuilder(sb.reverse().toString()).toString();
}

