    }

    int[] nsm = nextSmallerElementIndex(heights); // Calculate the nearest smaller element for each index
    int[] psm = preSmallerElementIndex(heights); // Calculate the nearest greater element for each index

    int maxArea = Integer.MIN_VALUE;
    for (int i = 0; i < heights.length; i++) {
        // Width of the rectangle is (psm[i] - nsm[i] - 1)
        // Height of the rectangle is heights[i]
        int area = heights[i] * (psm[i] - nsm[i] - 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int max = 0;
    int[] left = new int[heights.length];
    int[] right = new int[heights.length];
    Stack<Integer> stack = new Stack<>();

    // Calculate left boundaries
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            left[i] = 0;
        } else {
            left[i] = stack.peek() + 1;
        }
        stack.push(i);
    }

    stack.clear();

    // Calculate right boundaries
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            right[i] = heights.length - 1;
        } else {
            right[i] = stack.peek() - 1;
        }
        stack.push(i);
    }

    // Calculate max area
    for (int i = 0; i < heights.length; i++) {
        int width = right[i] - left[i] + 1;
        max = Math.max(max, width * heights[i]);
    }

    return max;
}

public static int largestRectangleArea(int[] heights) {
    Deque<int[]> stack = new ArrayDeque<>();
    int maxArea = 0;
    int n = heights.length;

    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];

        while (!stack.isEmpty() && h <= stack.peek()[1]) {
            int[] popped = stack.pop();
            int width = stack.isEmpty() ? i : i - stack.peek()[0] - 1;
            int area = popped[1] * width;
            maxArea = Math.max(maxArea, area);
        }
        stack.push(new int[]{i, h});
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int[][] directions = {{0, 1}, {1, 0}};

    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    if (n == 0) return new int[0];

    int i = 0, j = 0, k = 0, len = m * n;
    int[] result = new int[len];
    int count = 0;
    boolean directionChanged = false;

    while (count < len) {
        result[count++] = mat[i][j];

        int nextI = i + directions[k][0], nextJ = j + directions[k][1];
        if (nextI < 0 || nextI >= m || nextJ < 0 || nextJ >= n || mat[nextI][nextJ] == 0) {
            if (!directionChanged) {
                k = (k + 1) % 2;
                directionChanged = true;
            }
            nextI = i + directions[k][0], nextJ = j + directions[k][1];
            if (nextI < 0 || nextI >= m || nextJ < 0 || nextJ >= n) {
                break;
            }
        }
        i = nextI;
        j = nextJ;
    }

    return result;
}

