    int[] result = new int[rows * cols];
    int index = 0;

    for (int diagonals = 0; diagonals < rows + cols - 1; diagonals++) {
        int direction = diagonals % 2 == 0 ? 1 : -1;
        for (int row = Math.max(0, diagonals - cols + 1); row < Math.min(rows, diagonals); row += direction) {
            int col = diagonals - row;
            result[index++] = mat[row][col];
        }
    }

    return result;
}

