        // Top right to bottom left
        while (i >= 0 && j < cols) {
            result[k++] = mat[i][j];
            i--;
            j++;
        }
        // Move to the next diagonal row
        if (j < cols) {
            i = k - 1;
            j++;
        } else {
            i++;
        }

        // Bottom left to top right
        while (i < rows && j >= 0) {
            result[k++] = mat[i][j];
            i++;
            j--;
        }
        // Move to the next diagonal column
        if (i < rows) {
            j = k - 1;
            i++;
        } else {
            j++;
        }
    }

    return result;
}

