    int[] result = new int[size];

    // Push the first element into the stack
    stack.push(mat[row][col]);
    result[0] = mat[row][col];

    while (true) {
        int prev = stack.pop();
        row += 1;
        col -= 1;

        // If the previous element is within bounds and not visited, push and add to result
        if (row < m && col >= 0 && prev != result[size - 1]) {
            stack.push(prev);
            result[size++] = prev;
        }

        // Check if the previous element is within bounds and not visited
        if (row >= m && col < n && prev != result[size - 1]) {
            stack.push(prev);
            result[size++] = prev;
        }

        // Push the previous element to the top
        if (!stack.isEmpty()) {
            row -= 1;
            col += 1;

            // If the previous element is within bounds and not visited, push and add to result
            if (row < m && col >= 0 && prev != result[size - 1]) {
                stack.push(prev);
                result[size++] = prev;
            }
        }

        // If the previous element is within bounds and not visited
        if (row >= m && col < n && prev != result[size - 1]) {
            stack.push(prev);
            result[size++] = prev;
        }

        // Check if there are no more elements to process
        if (stack.isEmpty()) {
            break;
        }
    }

    return result;
}

