    }

    int m = mat.length;
    int n = mat[0].length;
    List<Integer> resultList = new ArrayList<>();
    int rowCount = 0;
    int colCount = 0;

    while (rowCount < m && colCount < n) {
        resultList.add(mat[rowCount][colCount]);
        if (rowCount == m - 1 || colCount == n - 1) {
            if (rowCount > m - 1) {
                colCount++;
            } else if (colCount > n - 1) {
                rowCount++;
            }
        } else {
            if (colCount + 1 <= n - 1) {
                colCount++;
            } else {
                rowCount++;
            }
        }
    }

    return resultList.stream().mapToInt(i -> i).toArray();
}

public static int findSmallestInteger(int n) {
    if (n < 10) return n;

    int largestDigitIndex = n - 1;
    int largestDigit = n % 10;
    for (; largestDigitIndex >= 0 && n % (10 * largestDigitIndex) == 0; largestDigitIndex--) {
        largestDigit = n % (10 * largestDigitIndex);
    }

    int smallestSmaller = n % (10 * largestDigitIndex);
    while (largestDigit >= 0) {
        if (n % 10 <= smallestSmaller) {
            smallestSmaller = n % (10 * largestDigitIndex);
            largestDigit--;
        } else {
            break;
        }
    }

    // Update the digits
    n += (smallestSmaller / 10);
    n -= (smallestSmaller % 10) * 10;

    // Integer.rotate() is not supported in Java; manually adjust the digits
    n += largestDigit;

    return n;
}

public static int findSmallestInteger(int n) {
    if (n == 0) return 0; // The smallest integer is 0 if the input is 0

    String numStr = String.valueOf(n);
    char[] digits = numStr.toCharArray();

    // Find the first digit that is not in ascending order
    int i = 0;
    for (i = 0; i < digits.length - 1; i++) {
        if (digits[i] > digits[i + 1]) break;
    }

    if (i == digits.length - 1) { // If all digits are in ascending order, no permutation can be found
        return -1;
    }

    // Find the smallest digit to swap with the first digit that is not in ascending order
    int j = i + 1;
    for (j = i + 1; j < digits.length; j++) {
        if (digits[j] < digits[i]) {
            break;
        }
    }

    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the remaining digits in ascending order
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the array back to an integer
    return Integer.parseInt(new String(digits));
}

public static int findSmallestInteger(int n) {
    if (n == 0) return -1;

    char[] digits = Integer.toString(n).toCharArray();

    int index = n - 1;
    while (index > 0 && digits[index - 1] >= digits[index]) {
        index--;
    }

    if (index == 0) return -1; // If no such number exists

    int replacementIndex = n;
    for (int i = digits.length - 1; i >= index; i--) {
        if (digits[i] > digits[index - 1]) {
            replacementIndex = i;
            break;
        }
    }

    char temp = digits[index - 1];
    digits[index - 1] = digits[replacementIndex];
    digits[replacementIndex] = temp;

    Arrays.sort(digits);

    return Integer.parseInt(new String(digits));
}

