public static int findSmallestInteger(int n) {
    int[] digits = new int[String.valueOf(n).length()];
    int maxIndex = -1;

    // Extract digits from n and find the index of the maximum digit
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        if (n > maxIndex) {
            maxIndex = i;
        }
        n /= 10;
    }

    if (maxIndex == -1) {
        return -1; // All digits are the same
    }

    int smallestIndex = maxIndex;
    // Find the next smallest digit to swap with maxIndex
    for (int i = maxIndex; i < digits.length; i++) {
        if (digits[i] > digits[maxIndex] && digits[i] < digits[smallestIndex]) {
            smallestIndex = i;
        }
    }

    // Swap the digits at maxIndex and smallestIndex
    int temp = digits[maxIndex];
    digits[maxIndex] = digits[smallestIndex];
    digits[smallestIndex] = temp;

    // Sort the remaining digits
    Arrays.sort(digits);

    // Convert the digits back to an integer
    int result = 0;
    for (int i = digits.length - 1; i >= 0; i--) {
        result = result * 10 + digits[i];
    }

    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
    } else {
        boolean isEven = n % 2 == 0;
        String prefix = "000000000".substring((n - 1) / 2) + "8";
        String suffix = "000000000".substring((n - 1) / 2) + "0";
        Integer centerValue = isEven ? 4 : 3;

        int power = centerValue - 1;
        for (int i = 0; i <= power; i++) {
            String currentString = prefix + Integer.toBinaryString(centerValue).substring(i) + suffix;
            result.add(currentString);
        }
    }
    return result;
}

