public static boolean isBoomerang(int[][] points) {
    if (points.length < 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    return (y2 - y1) * (x3 - x1) != (y3 - y1) * (x2 - x1);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length < 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the determinant of the matrix that will be formed by the points
    int determinant = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If the determinant is not zero, the points do not form a boomerang
    return determinant != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length < 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1], x2 = points[1][0], y2 = points[1][1], x3 = points[2][0], y3 = points[2][1];

    boolean x1y1_x2y2 = (x1 * y2) - (x2 * y1);
    boolean x2y2_x3y3 = (x2 * y3) - (x3 * y2);
    boolean x3y3_x1y1 = (x3 * y1) - (x1 * y3);

    return (x1y1_x2y2 != 0 || x2y2_x3y3 != 0) && (x3y3_x1y1 != 0);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The input array must contain exactly three points.");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check the cross product of vectors AB and AC to determine if they are perpendicular
    int area = (x2 - x1) * (y3 - y1) - (x2 - x3) * (y2 - y1);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int index2 = 1;
    int index3 = 1;
    int index5 = 1;

    for (int i = 1; i < n; i++) {
        int minNum = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = minNum;

        if (minNum == nextMultipleOf2) {
            index2++;
        }
        if (minNum == nextMultipleOf3) {
            index3++;
        }
        if (minNum == nextMultipleOf5) {
            index5++;
        }

        nextMultipleOf2 *= 2;
        nextMultipleOf3 *= 3;
        nextMultipleOf5 *= 5;
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    if (n == 1) {
        return 1;
    }

    PriorityQueue<Long> pq = new PriorityQueue<>();
    Set<Long> visited = new HashSet<>();
    pq.offer(1L);
    visited.add(1L);

    long currentUgly = 0;
    for (int i = 1; i < n; i++) {
        currentUgly = pq.poll();
        visited.add(currentUgly);

        for (long factor : new long[]{2, 3, 5}) {
            long next = currentUgly * factor;
            if (!visited.contains(next)) {
                pq.offer(next);
                visited.add(next);
            }
        }
    }

    return (int) currentUgly;
}

