    int _2 = ugly[index2] * 2, _3 = ugly[index3] * 3, _5 = ugly[index5] * 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(_2, Math.min(_3, _5));
        ugly[i] = min;

        switch (min) {
            case _2:
                index2++;
                _2 = ugly[index2] * 2;
                break;
            case _3:
                index3++;
                _3 = ugly[index3] * 3;
                break;
            case _5:
                index5++;
                _5 = ugly[index5] * 5;
                break;
        }
    }

    return ugly[n - 1];
}

public static int nthUglyNumber(int n) {
    Arrays.fill(dp, 0);

    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i <= n; i++) {
        int nextUgly = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        dp[i] = nextUgly;

        if (nextUgly == dp[i2] * 2) i2++;
        if (nextUgly == dp[i3] * 3) i3++;
        if (nextUgly == dp[i5] * 5) i5++;
    }

    return dp[n];
}

