public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum number of perfect squares needed
        int srt = (int) Math.sqrt(i);
        for (int j = 1; j <= srt; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int sqrt = 1; sqrt * sqrt <= i; sqrt++) {
            dp[i] = Math.min(dp[i], dp[i - sqrt * sqrt] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    List<Integer> squares = new ArrayList<>();
    int i = 1;
    while (i * i <= n) {
        squares.add(i * i);
        i++;
    }
    Collections.sort(squares);

    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (i - square >= 0) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}

