    dp[1] = 1;

    for (int i = 2; i <= n; i++) {
        dp[i] = i; // Worst case is to use individual numbers

        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

